"""HTTP API for the K7 cloud speech service."""

from __future__ import annotations

import logging
import time

from fastapi import FastAPI, Request, UploadFile
from fastapi.exceptions import RequestValidationError
from fastapi.responses import JSONResponse, Response
from pydantic import BaseModel

from aliyun_speech import SpeechServiceError, synthesize_wav, transcribe_wav

MAX_AUDIO_BYTES = 10 * 1024 * 1024
logger = logging.getLogger("speech-service")

app = FastAPI(title="K7 Cloud Speech Service")


class TTSRequest(BaseModel):
    text: str


def _error(status_code: int, message: str) -> JSONResponse:
    return JSONResponse(status_code=status_code, content={"success": False, "error": message})


@app.middleware("http")
async def log_request(request: Request, call_next):
    started = time.perf_counter()
    try:
        response = await call_next(request)
    except Exception:
        logger.error(
            "path=%s status=500 elapsed_ms=%.1f",
            request.url.path,
            (time.perf_counter() - started) * 1000,
        )
        raise
    logger.info(
        "path=%s status=%d elapsed_ms=%.1f",
        request.url.path,
        response.status_code,
        (time.perf_counter() - started) * 1000,
    )
    return response


@app.exception_handler(RequestValidationError)
async def validation_error(_request: Request, _exc: RequestValidationError) -> JSONResponse:
    return _error(400, "Invalid request parameters")


@app.exception_handler(Exception)
async def internal_error(_request: Request, _exc: Exception) -> JSONResponse:
    return _error(500, "Internal server error")


@app.get("/health")
async def health() -> dict[str, str]:
    return {"status": "ok"}


@app.post("/asr", response_model=None)
async def asr(audio: UploadFile) -> dict[str, object] | JSONResponse:
    content = await audio.read(MAX_AUDIO_BYTES + 1)
    await audio.close()
    if len(content) > MAX_AUDIO_BYTES:
        return _error(413, "Audio file is too large")
    if len(content) < 12 or content[:4] != b"RIFF" or content[8:12] != b"WAVE":
        return _error(400, "Audio must be a non-empty WAV file")
    try:
        text = await transcribe_wav(content)
    except SpeechServiceError as exc:
        return _error(500 if exc.configuration else 502, str(exc) if exc.configuration else "ASR service failed")
    return {"success": True, "text": text}


@app.post("/tts", response_model=None)
async def tts(payload: TTSRequest) -> Response:
    text = payload.text.strip()
    if not text or len(text) > 1000:
        return _error(400, "Text must contain 1 to 1000 characters")
    try:
        wav = await synthesize_wav(text)
    except SpeechServiceError as exc:
        return _error(500 if exc.configuration else 502, str(exc) if exc.configuration else "TTS service failed")
    return Response(
        content=wav,
        media_type="audio/wav",
        headers={"Content-Disposition": 'inline; filename="speech.wav"'},
    )
"""Minimal Alibaba Cloud Bailian ASR/TTS adapter."""

from __future__ import annotations

import base64
import os
from typing import Any

import httpx
from dotenv import load_dotenv

load_dotenv()

_REGION_DOMAIN = "cn-beijing.maas.aliyuncs.com"
_TIMEOUT = httpx.Timeout(60.0, connect=10.0)


class SpeechServiceError(RuntimeError):
    """Safe error raised to the HTTP layer."""

    def __init__(self, message: str, *, configuration: bool = False) -> None:
        super().__init__(message)
        self.configuration = configuration


def _required_setting(name: str) -> str:
    value = os.getenv(name, "").strip()
    if not value or value.startswith("replace-with-"):
        raise SpeechServiceError("Speech service configuration is missing", configuration=True)
    return value


def _workspace_base_url() -> str:
    workspace_id = _required_setting("ALIYUN_WORKSPACE_ID")
    return f"https://{workspace_id}.{_REGION_DOMAIN}"


def _headers(api_key: str) -> dict[str, str]:
    return {"Authorization": f"Bearer {api_key}", "Content-Type": "application/json"}


async def _post_json(url: str, api_key: str, payload: dict[str, Any]) -> dict[str, Any]:
    try:
        async with httpx.AsyncClient(timeout=_TIMEOUT) as client:
            response = await client.post(url, headers=_headers(api_key), json=payload)
            response.raise_for_status()
            data = response.json()
    except (httpx.HTTPError, ValueError) as exc:
        raise SpeechServiceError("Alibaba Cloud speech request failed") from exc
    if not isinstance(data, dict):
        raise SpeechServiceError("Alibaba Cloud speech response was invalid")
    return data


async def transcribe_wav(audio: bytes) -> str:
    """调用阿里云 ASR 并返回识别文字。"""
    api_key = _required_setting("ALIYUN_API_KEY")
    model = _required_setting("ALIYUN_ASR_MODEL")
    data_uri = "data:audio/wav;base64," + base64.b64encode(audio).decode("ascii")
    payload = {
        "model": model,
        "messages": [
            {
                "role": "user",
                "content": [
                    {"type": "input_audio", "input_audio": {"data": data_uri}}
                ],
            }
        ],
        "stream": False,
    }
    data = await _post_json(
        f"{_workspace_base_url()}/compatible-mode/v1/chat/completions",
        api_key,
        payload,
    )
    try:
        text = data["choices"][0]["message"]["content"].strip()
    except (KeyError, IndexError, AttributeError, TypeError) as exc:
        raise SpeechServiceError("Alibaba Cloud ASR response was invalid") from exc
    if not text:
        raise SpeechServiceError("Alibaba Cloud ASR returned no text")
    return text


async def synthesize_wav(text: str) -> bytes:
    """调用阿里云 TTS 并返回 WAV 音频。"""
    api_key = _required_setting("ALIYUN_API_KEY")
    model = _required_setting("ALIYUN_TTS_MODEL")
    voice = _required_setting("ALIYUN_TTS_VOICE")
    data = await _post_json(
        f"{_workspace_base_url()}/api/v1/services/audio/tts/SpeechSynthesizer",
        api_key,
        {
            "model": model,
            "input": {
                "text": text,
                "voice": voice,
                "format": "wav",
                "sample_rate": 24000,
            },
        },
    )
    try:
        audio_url = data["output"]["audio"]["url"]
        if not isinstance(audio_url, str) or not audio_url:
            raise TypeError
    except (KeyError, TypeError) as exc:
        raise SpeechServiceError("Alibaba Cloud TTS response was invalid") from exc

    try:
        async with httpx.AsyncClient(timeout=_TIMEOUT) as client:
            response = await client.get(audio_url)
            response.raise_for_status()
            wav = response.content
    except httpx.HTTPError as exc:
        raise SpeechServiceError("Alibaba Cloud TTS audio download failed") from exc
    if len(wav) < 12 or wav[:4] != b"RIFF" or wav[8:12] != b"WAVE":
        raise SpeechServiceError("Alibaba Cloud TTS returned invalid WAV audio")
    return wav
